        if (f.required) names.add(f.name);
      }
      if (names.size) index.set(serviceType, names);
    }
  } catch {
    // Registry not bundled: RequiredFields degrades to a no-op (documented).
  }
  _requiredFieldIndex = index;
  return index;
}

